#include <algorithm>
#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> vals, mins;
    for (int i = 0; i < n; i++) {
        string op;
        cin >> op;
        if (op == "PUSH") {
            long long x;
            cin >> x;
            vals.push_back(x);
            mins.push_back(mins.empty() ? x : min(x, mins.back()));
        } else if (vals.empty()) {
            cout << "EMPTY\n";
        } else if (op == "POP") {
            cout << vals.back() << '\n';
            vals.pop_back();
            mins.pop_back();
        } else if (op == "TOP") {
            cout << vals.back() << '\n';
        } else {
            cout << mins.back() << '\n';
        }
    }
    return 0;
}

